// CSD_RATIONALE_BEGIN
// Root-cause diagnosis from attempt 32:
//
// FAILURE MODE A (19 examples, mode_M): No span appeared.
//   Cause: Verbose guidance confused the model; it spent all 900 steps discussing the rules
//   instead of solving the problem. Budget exhausted before << was ever written.
//   Fix: Concise guidance (~50 words) matching attempt 24 style (best accuracy=34.7%).
//
// FAILURE MODE B (9 examples, mode_I): Malformed span — long repetitive expressions.
//   Cause: The grammar accepts int(expr) as complete, but also accepts
//   int(expr) OP more_expr as a valid continuation. The model keeps generating after the
//   first complete int(…) because GenerateWithPrefixAndManagedSpan / CloseSpanWithinBudget
//   track the LONGEST complete prefix and then close — but only after budget exhaustion.
//   In attempt 32, CloseSpanWithinBudget consumed all remaining steps, and the model
//   filled them with repetitive arithmetic.
//   Fix: Phase 3 custom constrained loop calls CloseSpanIfComplete at EVERY step.
//   The span is closed at the FIRST complete parse (e.g., immediately after int(expr)
//   is finished), preventing any further expansion.
//
// FAILURE MODE C (3 examples): Unterminated spans.
//   Cause: EOS or dead-end inside span before >> was emitted.
//   Fix: Phase 4 fallback CloseSpanWithinBudget with full remaining budget.
//
// Strategy:
//   Phase 0: Close any inherited open span (up to 30 steps).
//   Phase 1: Free unconstrained generation with RenderedEndsWith(generated,"<<") detection.
//            Run until << appears OR 78% of budget (702/900) is consumed.
//            Break immediately on << detection so the model can't open a second one.
//   Phase 2: Force-open a constrained span if the model never wrote <<.
//   Phase 3: Per-step constrained generation: call CloseSpanIfComplete first;
//            close immediately if complete, else generate one more ConstrainedStep.
//            This closes the span at the first valid int(expr) and stops runaway generation.
//   Phase 4: CloseSpanWithinBudget fallback for any remaining open span.
//
// Guidance: Short, clear, no extra rules that confuse the model. Same style as attempt 24
// (which achieved the best accuracy of 34.7%).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// INVARIANT 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 0 (CloseSpanWithinBudget): Its postcondition directly guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut), so the invariant holds after Phase 0.
//
// Phase 1 loop (free generation):
//   The loop guard !insideConstrainedOut means insideConstrainedOut=false throughout
//   each iteration body, making the antecedent false. The only place we set
//   insideConstrainedOut:=true is when RenderedEndsWith detects "<<", and at that point
//   we set currentConstrainedOut:=[], which satisfies parser.IsValidPrefix([]) by the
//   method's requires clause. The loop guard then fails and we exit.
//
// Phase 2 (OpenConstrainedSpan): Postcondition gives insideOut:=true, currentOut:=[].
//   parser.IsValidPrefix([]) holds by requires. Invariant preserved.
//
// Phase 3 loop (constrained generation):
//   closed branch: CloseSpanIfComplete postcondition guarantees
//     insideOut==>parser.IsValidPrefix(currentOut) and !insideOut==>currentOut==[].
//     When closed=true, insideOut becomes false; invariant vacuously true.
//   else branch (ConstrainedStep + AppendConstrainedToken): ConstrainedStep returns a
//     token that is parser-valid at currentConstrainedOut (by its postcondition).
//     We only call AppendConstrainedToken when IsTokenValidNext is true, so
//     currentConstrainedOut+[next] remains parser.IsValidPrefix by parser monotonicity.
//   EOS break: state unchanged; invariant preserved from before EOS.
//
// Phase 4 (CloseSpanWithinBudget): Same as Phase 0, postcondition guarantees invariant.
//
// INVARIANT 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 0: CloseSpanWithinBudget postcondition: |g0| <= |generated_init| + b0.
//   We set steps:=b0, so |generated|=|g0|<=|generatedPrefix|+b0=|generatedPrefix|+steps.
//
// Phase 1 loop: Each iteration increments steps by 1.
//   Non-EOS token: generated grows by 1 (one append), steps grows by 1. delta equal.
//   EOS: generated unchanged, steps grows by 1. Bound preserved (strict inequality after).
//   Entering constrained mode: only sets flags, no token append. Bound preserved.
//
// Phase 2 (OpenConstrainedSpan): Appends exactly 1 token (<<), steps+=1. Delta equal.
//
// Phase 3 loop: Each iteration increments steps by exactly 1.
//   closed branch: CloseSpanIfComplete appends at most 1 token (>>), steps+=1. Delta <=1.
//   else, valid branch: AppendConstrainedToken appends exactly 1 token, steps+=1. Delta=1.
//   else, EOS/invalid branch: generated unchanged, steps+=1. Bound preserved.
//   EOS tokens inside ConstrainedStep consume 1 step but are not appended to generated,
//   so visible growth is at most the consumed token budget per iteration.
//
// Phase 4: CloseSpanWithinBudget appends at most b4 tokens, steps:=maxSteps=steps+b4.
//   |generated|<=|generated_before|+b4<=|generatedPrefix|+steps_before+b4
//           =|generatedPrefix|+maxSteps=|generatedPrefix|+steps. Bound preserved.
// CSD_PROOF_SKETCH_END

  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  cost := 0;

  if maxSteps == 0 {
    cost := 0;
  } else {
    helpers.AppendTaskGuidance(lm,
      "Solve step by step. Write final answer as <<int(formula)>>. " +
      "Formula: bare variable names (no {} braces), numbers, +,-,*,/,//,%,(,),int() only. " +
      "ONE <<int(formula)>> block only, at the very end. No LaTeX, no **, no curly braces. " +
      "Example: <<int(n_1 * price - n_2 * discount)>>");

    var steps: nat := 0;
    var prefixBudget: nat := (maxSteps * 78) / 100;

    // Phase 0: Close any inherited open span with a small budget
    if insideConstrainedOut && steps < maxSteps {
      var b0: nat := if maxSteps - steps > 30 then 30 else maxSteps - steps;
      var g0, i0, c0 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, b0
      );
      generated := g0;
      insideConstrainedOut := i0;
      currentConstrainedOut := c0;
      steps := steps + b0;
    }

    // Phase 1: Free generation until << detected or prefixBudget reached
    while steps < prefixBudget && !insideConstrainedOut
      invariant 0 <= steps <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut ==> currentConstrainedOut == []
      invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases maxSteps - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }

    // Phase 2: Force-open constrained span if none appeared during free generation
    if !insideConstrainedOut && steps < maxSteps {
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    }

    // Phase 3: Constrained generation with per-step CloseSpanIfComplete check.
    // This closes the span at the FIRST complete parse, preventing runaway generation.
    while insideConstrainedOut && steps < maxSteps
      invariant 0 <= steps <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut ==> currentConstrainedOut == []
      invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases maxSteps - steps
    {
      var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
      if closed {
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      } else {
        var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
        steps := steps + 1;
        if next == eosToken {
          break;
        }
        var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
        if valid {
          var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        }
      }
    }

    // Phase 4: Fallback close with full remaining budget
    if insideConstrainedOut && steps < maxSteps {
      var b4: nat := maxSteps - steps;
      var g4, i4, c4 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, b4
      );
      generated := g4;
      insideConstrainedOut := i4;
      currentConstrainedOut := c4;
      steps := maxSteps;
    }

    cost := steps;
  }

